                if not (0 < sample[index] < float("inf")):
                    record["status"] = "INVALID_TIMING_PARENT_RETAINED"; complete = False; break
            if not complete:
                break
            record["pairs_us"].append({"parent":sample[0],"keyed":sample[1],"order":"AB" if block%2==0 else "BA"})
        if complete and time.time() < deadline:
            ds = sorted(r["parent"]-r["keyed"] for r in record["pairs_us"])
